import{_ as a,c as i,o as s,ag as t}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Security and Compliance","description":"TLS, HIPAA, and security hardening","frontmatter":{"title":"Security and Compliance","description":"TLS, HIPAA, and security hardening"},"headers":[],"relativePath":"engine/security_and_compliance.md","filePath":"engine/security_and_compliance.md","lastUpdated":1788476353000}'),n={name:"engine/security_and_compliance.md"};function r(l,e,o,c,d,h){return s(),i("div",null,e[0]||(e[0]=[t(`<h1 id="security-and-compliance" tabindex="-1">Security and Compliance <a class="header-anchor" href="#security-and-compliance" aria-label="Permalink to &quot;Security and Compliance&quot;">​</a></h1><p>OIE is designed to handle sensitive healthcare data securely. This page covers TLS configuration, access control, HIPAA considerations, and security hardening.</p><h2 id="transport-layer-security-tls" tabindex="-1">Transport Layer Security (TLS) <a class="header-anchor" href="#transport-layer-security-tls" aria-label="Permalink to &quot;Transport Layer Security (TLS)&quot;">​</a></h2><h3 id="server-tls-configuration" tabindex="-1">Server TLS configuration <a class="header-anchor" href="#server-tls-configuration" aria-label="Permalink to &quot;Server TLS configuration&quot;">​</a></h3><p>The server uses HTTPS for all API and Administrator communications:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Supported TLS protocol versions</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.client.protocols</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = TLSv1.3,TLSv1.2</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.server.protocols</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = TLSv1.3,TLSv1.2,SSLv2Hello</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Cipher suites (strong ciphers only)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.ciphersuites</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = TLS_CHACHA20_POLY1305_SHA256,...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ephemeral DH key size</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.ephemeraldhkeysize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 2048</span></span></code></pre></div><h3 id="keystore-management" tabindex="-1">Keystore management <a class="header-anchor" href="#keystore-management" aria-label="Permalink to &quot;Keystore management&quot;">​</a></h3><p>The server keystore stores TLS certificates:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = \${dir.appdata}/keystore.jks</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.storepass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 81uWxplDtB</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.keypass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 81uWxplDtB</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = JCEKS</span></span></code></pre></div><p><strong>For production:</strong></p><ol><li>Replace the default self-signed certificate with a CA-signed certificate</li><li>Change the default keystore passwords</li><li>Use the <strong>TLS Manager</strong> web application (<code>https://&lt;host&gt;:8443/tls-manager/</code>) to manage certificates</li></ol><h3 id="connector-level-tls" tabindex="-1">Connector-level TLS <a class="header-anchor" href="#connector-level-tls" aria-label="Permalink to &quot;Connector-level TLS&quot;">​</a></h3><p>Individual connectors support TLS:</p><ul><li><strong>TCP Listener/Sender</strong> - TLS mode with configurable client authentication</li><li><strong>HTTP Listener/Sender</strong> - HTTPS endpoints</li><li><strong>SMTP Sender</strong> - STARTTLS or SSL/TLS</li><li><strong>File Reader/Writer</strong> - FTPS, SFTP</li><li><strong>Web Service</strong> - HTTPS SOAP endpoints</li></ul><h2 id="csrf-protection" tabindex="-1">CSRF protection <a class="header-anchor" href="#csrf-protection" aria-label="Permalink to &quot;CSRF protection&quot;">​</a></h2><p>The REST API requires an <code>X-Requested-With</code> header by default:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.require-requested-with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = true</span></span></code></pre></div><p>This prevents Cross-Site Request Forgery attacks. All API clients must include this header.</p><h2 id="cors-configuration" tabindex="-1">CORS configuration <a class="header-anchor" href="#cors-configuration" aria-label="Permalink to &quot;CORS configuration&quot;">​</a></h2><p>Control cross-origin access to the REST API:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolalloworigin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = *           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restrict in production</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolallowcredentials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = false</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolallowmethods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = GET, POST, DELETE, PUT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolallowheaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = Content-Type</span></span></code></pre></div><p><strong>For production:</strong> Replace <code>*</code> with the specific origin(s) that need access.</p><h2 id="authentication-and-access-control" tabindex="-1">Authentication and access control <a class="header-anchor" href="#authentication-and-access-control" aria-label="Permalink to &quot;Authentication and access control&quot;">​</a></h2><h3 id="password-policy" tabindex="-1">Password policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password policy&quot;">​</a></h3><p>Enforce strong passwords (see <a href="./user_management.html">User Management</a>).</p><p>All password policy properties default to <code>0</code> (disabled). To enforce a strong policy, configure values in <code>mirth.properties</code>:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minlength</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minupper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minlower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minnumeric</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minspecial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.retrylimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.lockoutperiod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.expiration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.graceperiod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.reuselimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.reuseperiod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 0</span></span></code></pre></div><h3 id="account-lockout" tabindex="-1">Account lockout <a class="header-anchor" href="#account-lockout" aria-label="Permalink to &quot;Account lockout&quot;">​</a></h3><p>Configure automatic lockout after failed login attempts:</p><ul><li><code>password.retrylimit</code> - Number of failed attempts before lockout</li><li><code>password.lockoutperiod</code> - Hours until automatic unlock (0 = manual unlock only)</li></ul><h3 id="multi-factor-authentication" tabindex="-1">Multi-factor authentication <a class="header-anchor" href="#multi-factor-authentication" aria-label="Permalink to &quot;Multi-factor authentication&quot;">​</a></h3><p>OIE supports extensible authentication through the <code>MultiFactorAuthenticationPlugin</code> abstract class, which extends <code>ServicePlugin</code>. After primary authentication succeeds, a registered MFA plugin can trigger secondary authentication via a client-side plugin.</p><h3 id="role-based-access-control-rbac" tabindex="-1">Role-based access control (RBAC) <a class="header-anchor" href="#role-based-access-control-rbac" aria-label="Permalink to &quot;Role-based access control (RBAC)&quot;">​</a></h3><p>The <code>rbac</code> extension provides role-based permissions for controlling which users can access specific channels and features.</p><h2 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h2><h3 id="data-at-rest" tabindex="-1">Data at rest <a class="header-anchor" href="#data-at-rest" aria-label="Permalink to &quot;Data at rest&quot;">​</a></h3><ul><li>Database credentials can be encrypted in the keystore</li><li>The <code>EncryptionUtil</code> scripting class provides AES encryption for message data</li><li>Attachments can be stored encrypted</li></ul><h3 id="data-in-transit" tabindex="-1">Data in transit <a class="header-anchor" href="#data-in-transit" aria-label="Permalink to &quot;Data in transit&quot;">​</a></h3><ul><li>All Administrator-to-server communication uses TLS</li><li>Connector-level encryption via TLS for supported protocols</li></ul><h3 id="keystore" tabindex="-1">Keystore <a class="header-anchor" href="#keystore" aria-label="Permalink to &quot;Keystore&quot;">​</a></h3><p>The JCEKS keystore provides:</p><ul><li>TLS certificate storage</li><li>Encryption key management</li><li>Secure credential storage</li></ul><h2 id="hipaa-considerations" tabindex="-1">HIPAA considerations <a class="header-anchor" href="#hipaa-considerations" aria-label="Permalink to &quot;HIPAA considerations&quot;">​</a></h2><p>OIE is used in HIPAA-regulated environments. Key considerations:</p><h3 id="technical-safeguards" tabindex="-1">Technical safeguards <a class="header-anchor" href="#technical-safeguards" aria-label="Permalink to &quot;Technical safeguards&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>OIE Feature</th></tr></thead><tbody><tr><td><strong>Access Control</strong></td><td>User authentication, RBAC extension</td></tr><tr><td><strong>Audit Controls</strong></td><td>Event logging, message tracking</td></tr><tr><td><strong>Integrity Controls</strong></td><td>Message validation, checksums</td></tr><tr><td><strong>Transmission Security</strong></td><td>TLS encryption on all channels</td></tr></tbody></table><h3 id="administrative-safeguards" tabindex="-1">Administrative safeguards <a class="header-anchor" href="#administrative-safeguards" aria-label="Permalink to &quot;Administrative safeguards&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Recommendation</th></tr></thead><tbody><tr><td><strong>Unique User IDs</strong></td><td>Create individual accounts (no shared logins)</td></tr><tr><td><strong>Password Management</strong></td><td>Configure strong password policy</td></tr><tr><td><strong>Access Logging</strong></td><td>Enable and retain event logs</td></tr><tr><td><strong>Automatic Logoff</strong></td><td>Configure session timeouts</td></tr></tbody></table><h3 id="audit-trail" tabindex="-1">Audit trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit trail&quot;">​</a></h3><p>OIE maintains an audit trail through:</p><ul><li><strong>Event Browser</strong> - All user and system actions are logged</li><li><strong>Message Browser</strong> - Full message lifecycle tracking</li><li><strong>Server Logs</strong> - Detailed system logs</li></ul><h2 id="security-hardening-checklist" tabindex="-1">Security hardening checklist <a class="header-anchor" href="#security-hardening-checklist" aria-label="Permalink to &quot;Security hardening checklist&quot;">​</a></h2><h3 id="server-configuration" tabindex="-1">Server configuration <a class="header-anchor" href="#server-configuration" aria-label="Permalink to &quot;Server configuration&quot;">​</a></h3><ul><li>[ ] Change default admin password</li><li>[ ] Change default keystore passwords</li><li>[ ] Replace self-signed TLS certificate with CA-signed</li><li>[ ] Restrict bind addresses (<code>http.host</code>, <code>https.host</code>) if not all interfaces needed</li><li>[ ] Set strong password policy</li><li>[ ] Enable account lockout</li><li>[ ] Restrict CORS origins</li><li>[ ] Keep <code>server.api.require-requested-with = true</code></li></ul><h3 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li>[ ] Use a firewall to restrict access to ports 8080 and 8443</li><li>[ ] Place OIE behind a reverse proxy for additional security layers</li><li>[ ] Use network segmentation for healthcare systems</li><li>[ ] Restrict connector ports to necessary interfaces</li></ul><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h3><ul><li>[ ] Use a dedicated database user with minimal privileges</li><li>[ ] Enable TLS for database connections</li><li>[ ] Use strong database passwords</li><li>[ ] Enable database audit logging</li></ul><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h3><ul><li>[ ] Enable and monitor the Event Browser</li><li>[ ] Configure log retention</li><li>[ ] Set up alerts for errors and security events</li><li>[ ] Regularly back up the database and configuration</li><li>[ ] Keep OIE updated to the latest version</li><li>[ ] Review and prune old message data</li></ul><h3 id="custom-libraries" tabindex="-1">Custom libraries <a class="header-anchor" href="#custom-libraries" aria-label="Permalink to &quot;Custom libraries&quot;">​</a></h3><ul><li>[ ] Set <code>server.includecustomlib = false</code> unless needed</li><li>[ ] Use Resources instead of custom-lib for channel-specific libraries</li><li>[ ] Audit third-party libraries for vulnerabilities</li></ul><h2 id="reporting-security-vulnerabilities" tabindex="-1">Reporting security vulnerabilities <a class="header-anchor" href="#reporting-security-vulnerabilities" aria-label="Permalink to &quot;Reporting security vulnerabilities&quot;">​</a></h2><p>Report security vulnerabilities to: <strong><a href="mailto:security@openintegrationengine.org" target="_blank" rel="noreferrer">security@openintegrationengine.org</a></strong></p><p>See <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> for the full security policy.</p>`,65)]))}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
